using System.Collections.Generic;

namespace MyTube.Backend.Application.AI;

/// <summary>
/// Structured classification, canonical naming, and summary generated by SmartRoute AI.
/// </summary>
public record MediaClassificationResult
{
    public string MediaType { get; init; } = "Video"; // "Video" or "Audio"
    public string Category { get; init; } = "Unclassified"; // Exactly one of the 10 Video or 9 Audio categories
    public string CanonicalTitle { get; init; } = string.Empty;
    public string? Language { get; init; } // e.g. "Kannada", "English", "Hindi"
    public int? ReleaseYear { get; init; }
    public string? Artist { get; init; }
    public string? ArtistOrDirector { get; init; } // Backward-compatible alias
    public string? SeasonEpisode { get; init; } // e.g. "S01E01"
    public string? Part { get; init; } // e.g. "Part01"
    public string PrimaryGenre { get; init; } = "General";
    public List<string> SecondaryGenres { get; init; } = new();
    public string Summary { get; init; } = string.Empty;
    public double Confidence { get; init; } = 1.0;
    public string ClassificationReason { get; init; } = string.Empty;
    public string SuggestedFileName { get; init; } = string.Empty;
}
